steps.command:
$desktopKey = "HKCU:\Control Panel\Desktop"
$backupKey = "HKCU:\Software\FalconOptimizer\Backups"
$backup = (Get-ItemProperty -Path $backupKey -Name UserPreferencesMask_PreFalcon -ErrorAction SilentlyContinue).UserPreferencesMask_PreFalcon
if ($null -ne $backup) {
  Set-ItemProperty -Path $desktopKey -Name UserPreferencesMask -Type Binary -Value $backup
  Remove-ItemProperty -Path $backupKey -Name UserPreferencesMask_PreFalcon -ErrorAction SilentlyContinue
  Write-Output "Restored prior UserPreferencesMask backup."
} else {
  Write-Output "No Falcon backup found; leaving current UserPreferencesMask unchanged."
}
